const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Washington D.C. location
  const dcPoint = ee.Geometry.Point([-77.0369, 38.9072]);

  // Date ranges
  const date1Start = '2019-01-29';
  const date1End = '2019-01-30';
  const date2Start = '2019-02-05';
  const date2End = '2019-02-06';

  // Load ERA5 daily temperature data
  const era5 = ee.ImageCollection('ECMWF/ERA5/DAILY');

  // Filter for January 29, 2019
  const col1 = era5.filterDate(date1Start, date1End)
    .select('mean_2m_air_temperature');

  // Filter for February 5, 2019
  const col2 = era5.filterDate(date2Start, date2End)
    .select('mean_2m_air_temperature');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 29, 2019 Images: ${size1}`);
  console.log(`Feb 5, 2019 Images: ${size2}`);

  // Check if data exists
  if (size1 === 0 || size2 === 0) {
    console.log('No data available for one or both dates.');
    console.log('C1');
    return;
  }

  // Get mean temperature for each date
  const img1 = col1.first();
  const img2 = col2.first();

  const temp1Result = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dcPoint,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const temp2Result = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dcPoint,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const temp1 = temp1Result['mean_2m_air_temperature'];
  const temp2 = temp2Result['mean_2m_air_temperature'];

  console.log(`Jan 29, 2019 Temp: ${(temp1 - 273.15).toFixed(2)}°C`);
  console.log(`Feb 5, 2019 Temp: ${(temp2 - 273.15).toFixed(2)}°C`);

  // Validate results
  if (temp1 === null || temp1 === undefined || temp2 === null || temp2 === undefined) {
    console.log('Temperature calculation failed.');
    console.log('C3');
    return;
  }

  // Convert from Kelvin to Celsius
  const tempC1 = temp1 - 273.15;
  const tempC2 = temp2 - 273.15;

  // Sanity check: DC temperatures should be between -30 and +40°C
  if (tempC1 < -30 || tempC1 > 40 || tempC2 < -30 || tempC2 > 40) {
    console.log('Temperature out of valid range for Washington D.C.');
    console.log('C3');
    return;
  }

  const difference = Math.abs(tempC2 - tempC1);
  console.log(`Temperature Difference: ${difference.toFixed(2)}°C`);

  // Check if difference >= 24°C
  if (difference >= 24) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
